pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint8 playCount, uint48 initialPot, uint48 feePaid) public {
        vm.assume(playCount <= 5);
        vm.assume(initialPot <= 1e12);
        vm.assume(feePaid <= 1e12);

        address player = address(0x1234);
        for (uint8 i = 0; i < playCount; i++) {
            vm.deal(player, 10);
            vm.prank(player);
            try c.play{value: 10}() {} catch {}
        }

        uint256 pot = c.pot();
        uint256 contractBalance = address(c).balance;
        uint256 bankBalance = address(c.bank()).balance;

        assertTrue(pot <= contractBalance);
    }
}
